-- 108_variables_por_poblacion.sql | distribucion de las 39 variables del modelo por poblacion. Lo que importa no es la media sino pct_cero y pct_nulo: min_sldopasi06m entra con COALESCE(...,0), asi que un no cliente de IBK recibe el peor valor posible en vez de un faltante
SELECT variable,
       round(media_ibk, 5)     AS media_ibk,
       round(media_resto, 5)   AS media_resto,
       round(media_ssff, 5)    AS media_ssff,
       round(cero_ibk, 2)      AS pct_cero_ibk,
       round(cero_resto, 2)    AS pct_cero_resto,
       round(cero_ssff, 2)     AS pct_cero_ssff,
       round(nulo_ibk, 2)      AS pct_nulo_ibk,
       round(nulo_resto, 2)    AS pct_nulo_resto,
       round(nulo_ssff, 2)     AS pct_nulo_ssff
FROM (
    SELECT avg(CASE WHEN g.pob = 'IBK' THEN TRY_CAST(s.probabilidad AS DOUBLE) END) AS mi0,
           100.0 * sum(CASE WHEN g.pob = 'IBK' AND TRY_CAST(s.probabilidad AS DOUBLE) = 0 THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'IBK' THEN 1 ELSE 0 END),0) AS zi0,
           100.0 * sum(CASE WHEN g.pob = 'IBK' AND s.probabilidad IS NULL THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'IBK' THEN 1 ELSE 0 END),0) AS ui0,
           avg(CASE WHEN g.pob = 'RESTO_TOP4' THEN TRY_CAST(s.probabilidad AS DOUBLE) END) AS mr0,
           100.0 * sum(CASE WHEN g.pob = 'RESTO_TOP4' AND TRY_CAST(s.probabilidad AS DOUBLE) = 0 THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'RESTO_TOP4' THEN 1 ELSE 0 END),0) AS zr0,
           100.0 * sum(CASE WHEN g.pob = 'RESTO_TOP4' AND s.probabilidad IS NULL THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'RESTO_TOP4' THEN 1 ELSE 0 END),0) AS ur0,
           avg(CASE WHEN g.pob = 'SSFF' THEN TRY_CAST(s.probabilidad AS DOUBLE) END) AS ms0,
           100.0 * sum(CASE WHEN g.pob = 'SSFF' AND TRY_CAST(s.probabilidad AS DOUBLE) = 0 THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'SSFF' THEN 1 ELSE 0 END),0) AS zs0,
           100.0 * sum(CASE WHEN g.pob = 'SSFF' AND s.probabilidad IS NULL THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'SSFF' THEN 1 ELSE 0 END),0) AS us0,
           avg(CASE WHEN g.pob = 'IBK' THEN TRY_CAST(s.woe_prm_decresldo12m AS DOUBLE) END) AS mi1,
           100.0 * sum(CASE WHEN g.pob = 'IBK' AND TRY_CAST(s.woe_prm_decresldo12m AS DOUBLE) = 0 THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'IBK' THEN 1 ELSE 0 END),0) AS zi1,
           100.0 * sum(CASE WHEN g.pob = 'IBK' AND s.woe_prm_decresldo12m IS NULL THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'IBK' THEN 1 ELSE 0 END),0) AS ui1,
           avg(CASE WHEN g.pob = 'RESTO_TOP4' THEN TRY_CAST(s.woe_prm_decresldo12m AS DOUBLE) END) AS mr1,
           100.0 * sum(CASE WHEN g.pob = 'RESTO_TOP4' AND TRY_CAST(s.woe_prm_decresldo12m AS DOUBLE) = 0 THEN 1 ELSE 0 END) / nullif(sum(CASE WHEN g.pob = 'RESTO_TOP4' THEN 1 ELSE 0 END),0) AS zr1,
