    ARRAY[q.mi0, q.mi1, q.mi2, q.mi3, q.mi4, q.mi5, q.mi6, q.mi7, q.mi8, q.mi9, q.mi10, q.mi11, q.mi12, q.mi13, q.mi14, q.mi15, q.mi16, q.mi17, q.mi18, q.mi19, q.mi20, q.mi21, q.mi22, q.mi23, q.mi24, q.mi25, q.mi26, q.mi27, q.mi28, q.mi29, q.mi30, q.mi31, q.mi32, q.mi33, q.mi34, q.mi35, q.mi36, q.mi37, q.mi38], ARRAY[q.mr0, q.mr1, q.mr2, q.mr3, q.mr4, q.mr5, q.mr6, q.mr7, q.mr8, q.mr9, q.mr10, q.mr11, q.mr12, q.mr13, q.mr14, q.mr15, q.mr16, q.mr17, q.mr18, q.mr19, q.mr20, q.mr21, q.mr22, q.mr23, q.mr24, q.mr25, q.mr26, q.mr27, q.mr28, q.mr29, q.mr30, q.mr31, q.mr32, q.mr33, q.mr34, q.mr35, q.mr36, q.mr37, q.mr38], ARRAY[q.ms0, q.ms1, q.ms2, q.ms3, q.ms4, q.ms5, q.ms6, q.ms7, q.ms8, q.ms9, q.ms10, q.ms11, q.ms12, q.ms13, q.ms14, q.ms15, q.ms16, q.ms17, q.ms18, q.ms19, q.ms20, q.ms21, q.ms22, q.ms23, q.ms24, q.ms25, q.ms26, q.ms27, q.ms28, q.ms29, q.ms30, q.ms31, q.ms32, q.ms33, q.ms34, q.ms35, q.ms36, q.ms37, q.ms38],
